FARBE = {
 'gbr': '#e3a19b', 'gbr_h': '#b9554c',
 'fra': '#9ab8de', 'fra_h': '#3f6ea8',
 'deu': '#e6c15c', 'deu_h': '#a07a12',
 'bel': '#b9a3d4', 'bel_h': '#6f4f99',
 'por': '#9fd0a8', 'por_h': '#3f8a50',
 'ndl': '#f0b27a', 'ndl_h': '#c06a1c',
 'ita': '#8fd0cc', 'ita_h': '#2f8784',
 'esp': '#e8e0a6', 'esp_h': '#a89a3a',
 'rus': '#d9cfc1', 'usa': '#c5a48c', 'jpn': '#f0b6cb', 'jpn_h': '#c25d84',
 'ind': '#ffffff',
}
LAND = '#eeece6'
DEC = 0
SIMP = 0.25
MEER = '#dfeaf2'

def regions():
    L = land()
    geos = []
    for rid, macht, pts in R:
        geos.append([rid, macht, P(pts).intersection(L)])
    # Überlappungen entfernen: spätere Gebiete liegen oben
    for i in range(len(geos)):
        later = [g[2] for g in geos[i+1:]]
        if later:
            geos[i][2] = geos[i][2].difference(unary_union(later))
    return L, geos

def path(geom, prj):
    out = []
    polys = [geom] if geom.geom_type == 'Polygon' else list(getattr(geom, 'geoms', []))
    for p in polys:
        if p.is_empty or p.geom_type != 'Polygon' or p.area < 0.05:
            continue
        p = p.simplify(SIMP)
        for ring in [p.exterior] + list(p.interiors):
            cs = list(ring.coords)
            pts = [prj(x, y) for x, y in cs]
            out.append('M' + ' L'.join(f'{a:.{DEC}f} {b:.{DEC}f}' for a, b in pts) + 'Z')
    return ' '.join(out)

def svg(view, k, lon0, lat0, hot=None, task='', faerben=None, label='', extra='', shift=None, marker=None, hot_extra=None):
    """view=(w,h). hot: dict rid->(hot_id, aria). faerben: Funktion macht->farbe."""
    prj = lambda x, y: ((x - lon0) * k, (lat0 - y) * k)
    L, geos = regions()
    w, h = view
    o = [f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="{label}">',
         f'<rect width="{w}" height="{h}" fill="{MEER}"/>']
    # Gradnetz: Äquator
    ye = lat0 * k
    o.append(f'<path d="M0 {ye:.1f} H{w}" stroke="#a9bccb" stroke-width="1" stroke-dasharray="4 4"/>')
    o.append(f'<path d="{path(L, prj)}" fill="{LAND}" stroke="#9aa5ad" stroke-width=".6"/>')
    hot = hot or {}
    grouped = {}
    for rid, macht, g in geos:
        if g.is_empty:
            continue
        col = (faerben or (lambda m: FARBE[m]))(macht)
        if col is None:
            continue
        d = path(g, prj)
        if not d:
            continue
        sw = '1.2' if macht == 'ind' else '.6'
        stroke = '#55616b' if macht == 'ind' else '#7d8a94'
        el = f'<path d="{d}" fill="{col}" stroke="{stroke}" stroke-width="{sw}"/>'
        if rid in hot:
            hid = hot[rid][0]
            grouped.setdefault(hid, []).append((el, hot[rid][1]))
        else:
            o.append(el)
    hot_extra = hot_extra or {}
    for hid, (snip, aria) in hot_extra.items():
        grouped.setdefault(hid, []).append((snip, aria))
    o.append(extra)
    for hid, els in grouped.items():
        aria = els[0][1]
        o.append(f'<g class="hot" data-task="{task}" data-hot="{hid}" tabindex="0" role="button" aria-label="{aria}">' + ''.join(e for e, a in els) + '</g>')
    o.append('</svg>')
    return '\n'.join(o)

def pt(lon, lat, k, lon0, lat0):
    return ((lon - lon0) * k, (lat0 - lat) * k)
